class Solution {
    public boolean judgePoint24(int[] cards) {
        List<Double> nums = new java.util.ArrayList<>();
        for (int c : cards) nums.add((double) c);
        return solve(nums);
    }
    private boolean solve(List<Double> nums) {
        if (nums.size() == 1) return Math.abs(nums.get(0) - 24) < 1e-6;
        for (int i = 0; i < nums.size(); i++) {
            for (int j = 0; j < nums.size(); j++) {
                if (i == j) continue;
                List<Double> next = new java.util.ArrayList<>();
                for (int k = 0; k < nums.size(); k++)
                    if (k != i && k != j) next.add(nums.get(k));
                double a = nums.get(i), b = nums.get(j);
                double[] results = {a + b, a - b, a * b};
                for (double r : results) { next.add(r); if (solve(next)) return true; next.remove(next.size() - 1); }
                if (Math.abs(b) > 1e-6) { next.add(a / b); if (solve(next)) return true; next.remove(next.size() - 1); }
            }
        }
        return false;
    }
}

class Solution {
    public boolean judgePoint24(int[] cards) {
        double[] nums = new double[4];
        for (int i = 0; i < 4; i++) nums[i] = cards[i];
        return helper(nums, 4);
    }
    private boolean helper(double[] nums, int n) {
        if (n == 1) return Math.abs(nums[0] - 24.0) < 1e-6;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double a = nums[i], b = nums[j];
                double[] next = new double[n - 1];
                int idx = 0;
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) next[idx++] = nums[k];
                }
                double[] ops = {a + b, a - b, b - a, a * b};
                for (double op : ops) {
                    next[idx] = op;
                    if (helper(next, n - 1)) return true;
                }
                if (Math.abs(b) > 1e-6) {
                    next[idx] = a / b;
                    if (helper(next, n - 1)) return true;
                }
                if (Math.abs(a) > 1e-6) {
                    next[idx] = b / a;
                    if (helper(next, n - 1)) return true;
                }
            }
        }
        return false;
    }
}
